    private readonly Dictionary<Guid,CommitPlanCommand> _previews=[];
    private static T? Read<T>(BranchSnapshot s,string id)where T:class=>BranchOperations.Read<T>(s,id);
    private static bool Current(BranchSnapshot s,IEnumerable<EntityStamp> reads)=>reads.All(r=>(BranchOperations.Entity(s,r.EntityId)?.Revision??-1)==r.Revision);
    private static bool Same<T>(T a,T b)=>StrictJson.Serialize(a)==StrictJson.Serialize(b);
    private static bool Closed(BranchSnapshot s,string quest){var q=Read<QuestState>(s,"quest:"+quest);var receipt=s.Receipts.SingleOrDefault(r=>r.SemanticKey==quest+":resolution"&&r.ActionType=="main_quest_resolution");if(q is not{Lifecycle:QuestLifecycle.Closed,Outcome:QuestOutcome.Completed}||receipt is null)return false;var r=StrictJson.Deserialize<MainQuestResolution>(receipt.ResultJson);return r.Quest==quest&&r.Instance==q.Instance&&r.Outcome=="completed";}
    public async ValueTask<FinaleLaunchPreview> PreviewAsync()
