        Check(quest is{Lifecycle:QuestLifecycle.Active,Outcome:null}&&quest.Instance!=Guid.Empty,"actual_active_Q604");Check(Closed(s,"Q-602")&&Closed(s,"Q-603"),"actual_closed_Q602_and_Q603");Check(!s.Receipts.Any(r=>r.SemanticKey=="Q-604:resolution"),"final_departure_already_completed");
        var original=s.Receipts.SingleOrDefault(r=>r.SemanticKey=="Q-104:resolution"&&r.ActionType=="tidegate_vessel_handover");var ownership=original is null?null:StrictJson.Deserialize<TidegateHandover>(original.ResultJson);Check(ship is not null&&ship.Instance!=Guid.Empty&&s.Entities.Count(e=>e.Kind=="shared_vessel")==1&&ship.Instance.ToString()==ownership?.VesselInstance&&ownership.VesselDefinition=="GLIMMER"&&ship.DockRegion=="R6"&&ship.WatchOfficer=="N-DECKWATCH"&&ship.Spaces.SequenceEqual(new[]{"HUB-S01","HUB-S02","HUB-S03"}),"same_actual_Q104_glimmer_and_R6_source_dock");
        var binding=ship is null?null:Read<VesselInteriorBinding>(s,"vessel:interior:"+ship.Instance);string actualInteriorHash=Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(System.Text.Encoding.UTF8.GetBytes(StrictJson.Serialize(interior.Scenes)))).ToLowerInvariant();Check(binding is not null&&binding.Instance==ship?.Instance&&binding.PackageVersion==interior.Version&&binding.GeometrySha256==actualInteriorHash&&binding.HandoverReceipt==original?.ReceiptId,"actual_current_source_interior_binding");
        var chart=interior.Scenes.Single(x=>x.Id=="HUB-S02");var chartStand=chart.Spots.Single(x=>x.Id=="HUB-S02.chart").Stand;Check(actor is not null&&actor.Scene==chart.Id&&actor.Position.Distance(chartStand)<=2.5&&new NavigationGrid(chart).CanStand(actor.Position,true),"actual_HUB_S02_chart_position");
        var spaceSources=ImmutableArray.CreateBuilder<string>();foreach(string scene in VesselInteriorRules.Spaces){var space=Read<VesselSpace>(s,"ship-space:"+scene);if(space is null){issues.Add("actual_registered_space:"+scene);continue;}var source=s.Receipts.SingleOrDefault(r=>r.ReceiptId==space.AuthorityReceipt&&r.ActionType=="ship_space_verified");Check(source is not null&&ship is not null&&space.Instance==ship.Instance&&space.Scene==scene&&new NavigationGrid(interior.Scenes.Single(g=>g.Id==scene)).CanStand(space.Landing,true)&&new NavigationGrid(interior.Scenes.Single(g=>g.Id==scene)).CanStand(space.TransferStand,true)&&(scene!="HUB-S02"||space.TransferStand==chartStand)&&Current(s,space.GateReads)&&Same(StrictJson.Deserialize<VesselSpace>(source.ResultJson) with{AuthorityReceipt=space.AuthorityReceipt},space),"current_same_vessel_space:"+scene);spaceSources.Add(space.AuthorityReceipt);}
