        Check(frozen is not null&&seal is not null&&Same(StrictJson.Deserialize<FrozenPreparation>(seal.ResultJson),frozen)&&frozen.Release==s.ReleaseId&&frozen.SourceBranch==repository.Session.Branch&&frozen.VesselInstance==ship?.Instance&&frozen.Q604Instance==quest?.Instance,"actual_current_sealed_preparation");
        if(frozen is not null){var saved=await checkpoints.FindAsync(frozen.PreFinalCheckpoint);Check(saved is not null&&saved.Id==frozen.PreFinalCheckpoint&&saved.Profile==repository.Session.Profile&&saved.SourceBranch==frozen.SourceBranch&&saved.Release==frozen.Release&&saved.Slot=="protected:pre-final:"+frozen.Id,"actual_protected_prefinal_checkpoint");Check(frozen.Preparation.Towers.Length==6&&frozen.Preparation.Towers.All(t=>t.Safe&&t.Baseline&&t.Operators&&Read<Mist.Core.Engineering.TowerReadiness>(s,"readiness:"+t.Tower) is{Safe:true,Baseline:true,Operators:true}),"six_actual_current_baselines");Check(frozen.ReservedResources.Count>0&&frozen.ReservedResources.All(p=>s.Balances.GetValueOrDefault(p.Key)>=p.Value),"sealed_installed_resources_intact");}
        var commitmentIds=s.Entities.Where(e=>e.Kind=="high_risk_commitment").Select(e=>e.Id).Order().ToImmutableArray();var transportIds=s.Entities.Where(e=>e.Kind=="transport_segment").Select(e=>e.Id).Order().ToImmutableArray();var riskSource=risk is null?null:s.Receipts.SingleOrDefault(r=>r.ReceiptId==risk.SourceReceipt&&r.ActionType=="high_risk_register_verified");Check(risk is not null&&riskSource is not null&&Same(StrictJson.Deserialize<RiskRegisterVerification>(riskSource.ResultJson),new RiskRegisterVerification(risk.Version,risk.CommitmentIds,risk.TransportIds))&&risk.CommitmentIds.Order().SequenceEqual(commitmentIds)&&risk.TransportIds.Order().SequenceEqual(transportIds),"actual_current_complete_risk_register");Check(commitmentIds.All(id=>Read<HighRiskCommitment>(s,id) is{} c&&(!c.Accepted||!c.OnsiteRequired||c.SafelyHandedOver||c.ExplicitlySuspended))&&transportIds.All(id=>Read<TransportSegment>(s,id) is{} t&&(!t.CargoInTransit||t.Completed)),"all_high_risk_and_actual_cargo_safely_handed_over");
        Check(!s.Entities.Where(e=>e.Kind=="event").Select(e=>StrictJson.Deserialize<EventSession>(e.Json)).Any(e=>e.State==EventLifecycle.Running),"foreground_event_handover");
        var task="R6-Q604-W-DEPARTURE";var draft=await repository.GetDraftAsync(task);var meaning=Read<Mist.Core.ChapterTwo.ChapterWorldMeaning>(s,"proposal:Q-604");Check(chapter is{QualificationViewed:true}&&chapter.PreparationDecision is "continue_preparation" or "accept_base_directions"&&meaning is not null&&meaning.DraftHash==draft?.Hash&&meaning.Fields.GetValueOrDefault("policy")=="not_selected"&&meaning.Fields.GetValueOrDefault("risks")=="current_handed_over"&&meaning.Fields.GetValueOrDefault("preparation")==chapter.PreparationDecision,"current_explicit_saved_Q604_handover_meaning");
        var landing=FinalePackage.LandingStand;var rf=destination.Scenes.Single(x=>x.Geometry.Id=="RF-S01").Geometry;Check(rf.Spots.Any(x=>x.Id=="RF-S01.berth"&&x.Stand==landing)&&new NavigationGrid(rf).CanStand(landing,true),"actual_source_RF_public_safe_landing");
        Guid token=Guid.NewGuid();FinaleDeparture? departure=null;if(issues.Count==0){var sources=ImmutableArray.Create(original!.ReceiptId,s.Receipts.Single(r=>r.SemanticKey=="Q-404:resolution").ReceiptId,s.Receipts.Single(r=>r.SemanticKey=="Q-602:resolution").ReceiptId,s.Receipts.Single(r=>r.SemanticKey=="Q-603:resolution").ReceiptId,seal!.ReceiptId,berth!.AuthorityReceipt,risk!.SourceReceipt).AddRange(spaceSources);departure=new(ship!.Instance,quest!.Instance,frozen!.Id,frozen.PreFinalCheckpoint,"R6","RF",berth.Scene,berth.Boarding,berth.AuthorityReceipt,"RF-S01",landing,destination.GeometrySha256("RF-S01"),sources,risk.SourceReceipt);var canonical=catalog.Quests.Single(q=>q.Id=="Q-604").Reward;if(canonical.Bundle.Experience!=1440||canonical.Bundle.Marks!=300||canonical.Bundle.Parts!=4||!canonical.Items.Contains("TL-04"))throw new InvalidDataException("Q604原件奖励与实际起航结算不符。");var changes=ImmutableArray.Create(BranchOperations.Change(s,"quest:Q-604","quest",quest.Close(QuestOutcome.Completed)),BranchOperations.Change(s,"ship:glimmer","shared_vessel",ship with{DockRegion="RF"}),BranchOperations.Change(s,"actor","actor",actor! with{Scene="RF-S01",Position=landing,ActionClock=actor.ActionClock+1}),BranchOperations.Change(s,"final:actual-departure","finale_departure",departure));var items=canonical.Items.Select(id=>new ItemChange("R6:Q-604:original:"+id,id,"new","","player","hero",null)).ToImmutableArray();var reads=s.Entities.Select(e=>e.Id).Concat(new[]{"actor","ship:glimmer","quest:Q-604","final:actual-departure","final:preparation","final:commitments","berth:R6"}).Distinct().ToArray();_previews[token]=BranchOperations.Plan(repository,s,"Q-604:resolution","network_finale_departure",changes,reads,departure,items:items,balances:[new("experience",1440),new("marks",300),new("parts",4)],draft:new(task,draft?.Id,draft?.Revision??0,draft?.Hash));}return new(token,issues.Count==0,issues.ToImmutable(),departure);
    }
    public async ValueTask<CommandResult> ConfirmAsync(Guid token)
    {
        if(!_previews.TryGetValue(token,out var command))return new(CommitStatus.Rejected,null,[new("preview_closed","Q-604","起航预览未就绪或已关闭。")]);
        var session=repository.Session;if(command.Context.Profile!=session.Profile||command.Context.Load!=session.Load||command.Context.Branch!=session.Branch||command.Context.ReleaseId!=session.ReleaseId)return new(CommitStatus.Rejected,null,[new("stale_load","Q-604","档案世代改变，请重新预览。")]);
        var known=await repository.FindReceiptAsync(command.Context.Branch,command.Context.Command);if(known is not null)return new(CommitStatus.AlreadyCommitted,known,[]);
        if(repository is not IEventLeaseStore leases)throw new InvalidOperationException("最终起航需要原子前景占用。");string owner="final-launch:"+command.Context.Command.Value;if(!await leases.TryLeasesAsync(command.Context.Load,owner,["input:foreground"]))return new(CommitStatus.Rejected,null,[new("foreground_owned","Q-604","另一项前景行动尚未交接。")]);
        try
        {
            // Recheck enumerated risks, checkpoint availability and balances under the same lease.
            // This catches additions as well as version changes before executing the original CAS plan.
            FinaleLaunchPreview fresh;try{fresh=await PreviewAsync();}catch(InvalidOperationException e){return new(CommitStatus.Rejected,null,[new("departure_changed","Q-604",e.Message)]);}
            ClosePreview(fresh.Token);if(!fresh.Ready||fresh.Departure is null||StrictJson.Serialize(fresh.Departure)!=command.Plan.ResultJson)return new(CommitStatus.Rejected,null,[new("departure_changed","Q-604",string.Join(",",fresh.Missing))]);
            return await repository.ExecuteAsync(command);
        }
        finally{await leases.ReleaseLeasesAsync(command.Context.Load,owner);}
    }
    public void ClosePreview(Guid token)=>_previews.Remove(token);
}
